// GENERATED by scripts/sync-shared.mjs from hotel-clash-api/engine — do not edit here.
// Player actions, ported from pages/game.js. Each handler validates its input
// and returns { ok: false, error } instead of throwing; rejected actions leave
// the state untouched.
import { pick } from './math.js';
import { clamp } from './core.js';
import { upgradeCost, facilityOffer, campaignCost, unlockLevel, roomCapacity, plotsOwned, nextPlotPrice, acquisitionOffer } from './insights.js';
import { coverDebtWithCoins } from './tick.js';
import {
  ROOM_TYPES,
  FACILITY_TYPES,
  STAFF_ROLES,
  FIRST_NAMES,
  TRAINING_PROGRAMS,
  POLICY_MESSAGES,
  SOCIAL_REWARDS,
  AD_REWARDS,
  AWAY_EARNINGS,
  WHEEL_SEGMENTS,
  WHEEL_SPINS_PER_DAY,
  HOTEL_VISITS_PER_DAY,
  CAMPAIGNS,
  INSURANCE_PLANS,
  ROOMS_PER_PLOT,
  ACQUISITION,
} from './data.js';

const fmt = (n) => Math.round(n).toLocaleString('en-US');
const reject = (error, extra = {}) => ({ ok: false, error, ...extra });
const nextNumericId = (list) => (list.length ? Math.max(...list.map((x) => (typeof x.id === 'number' ? x.id : 0))) + 1 : 1);
const utcDate = (t) => new Date(t).toISOString().slice(0, 10);

/**
 * Called for every accepted action with the real time since the previous one.
 * A long enough gap means the game was closed: add it to the unclaimed away
 * earnings (several absences add up, to the cap) and tell the UI.
 */
export function recordAwayTime(G, gapMs) {
  const { S } = G;
  if (S.gameOver || gapMs < AWAY_EARNINGS.minAwayMs) return;
  const ms = Math.min(((S.away && S.away.ms) || 0) + gapMs, AWAY_EARNINGS.maxAwayMs);
  const perDay = Math.max(0, (S.stats && S.stats.avgDayProfit) || 0);
  const amount = Math.floor((perDay * AWAY_EARNINGS.profitDaysPerHour * ms) / 3_600_000);
  if (amount <= 0) return;
  S.away = { ms, amount };
  G.emit({ kind: 'awayEarnings', ms, amount, doubledAmount: amount * 2 });
}

function insufficient(G, cost, message) {
  G.notify(message, true, 'money');
  G.emit({ kind: 'insufficientFunds', cost });
  return reject('insufficient_funds');
}

/** Not unlocked yet at this hotel level: tell the player when it unlocks. */
function locked(G, kind, id, label) {
  const need = unlockLevel(kind, id);
  if ((G.S.hotelLevel || 1) >= need) return false;
  G.notify(`🔒 ${label} unlock at hotel level ${need}. Grow your hotel's value to level up.`, false, 'info');
  return true;
}

export const ACTION_HANDLERS = {
  BUILD_ROOM(G, { roomType }) {
    const { S } = G;
    const rt = ROOM_TYPES.find((r) => r.type === roomType);
    if (!rt) return reject('unknown_room_type');
    if (locked(G, 'room', roomType, `${roomType} rooms`)) return reject('locked');
    if (S.rooms.length >= roomCapacity(S)) {
      G.notify(`🏗️ Your land is full (${roomCapacity(S)} rooms). Buy the next plot for $${fmt(nextPlotPrice(S))} to build more.`, false, 'error');
      return reject('no_land');
    }
    if (G.spendingPower() < rt.baseCost) {
      return insufficient(G, rt.baseCost, `💰 Need more funds! ${roomType} room costs $${fmt(rt.baseCost)}. You need $${fmt(rt.baseCost - G.spendingPower())} more. 💎 Buy Credits to expand faster!`);
    }
    S.rooms = [...S.rooms, { id: nextNumericId(S.rooms), type: roomType, price: rt.basePrice, occupied: false, quality: 2, guest: null }];
    G.pay(rt.baseCost);
    G.notify(`Built a new ${roomType} room for $${rt.baseCost}`);
    return { ok: true };
  },

  UPGRADE_ROOM(G, { roomId }) {
    const { S } = G;
    const room = S.rooms.find((r) => r.id === roomId);
    if (!room) return reject('unknown_room');
    if (room.quality >= 5) {
      G.notify(`Room ${room.id} (${room.type}) is already at maximum quality!`, false, 'info');
      return reject('max_quality');
    }
    // 600 · 1.6^quality (quality can be fractional after housekeeping).
    const cost = upgradeCost(room);
    if (G.spendingPower() < cost) {
      G.notify(`Need $${fmt(cost)} to upgrade Room ${room.id}, but only have $${fmt(G.spendingPower())}.`, false, 'error');
      return reject('insufficient_funds');
    }
    // FIX: quality can be fractional (housekeeping), so cap the +1 at 5.
    const quality = Math.min(5, room.quality + 1);
    S.rooms = S.rooms.map((r) => (r.id === roomId ? { ...r, quality } : r));
    G.pay(cost);
    G.notify(`Upgraded Room ${room.id} (${room.type}) to quality level ${quality}. Cost: $${fmt(cost)}`, true, 'success');
    return { ok: true };
  },

  SET_ROOM_PRICE(G, { roomId, price }) {
    const p = Number(price);
    if (!Number.isFinite(p) || p < 1 || p > 100000) return reject('invalid_price');
    if (!G.S.rooms.some((r) => r.id === roomId)) return reject('unknown_room');
    G.S.rooms = G.S.rooms.map((r) => (r.id === roomId ? { ...r, price: Math.round(p) } : r));
    return { ok: true };
  },

  HIRE_STAFF(G, { role }) {
    const { S, rand } = G;
    const def = STAFF_ROLES.find((r) => r.role === role);
    if (!def) return reject('unknown_role');
    if (G.spendingPower() < def.baseSalary * 5) {
      return insufficient(G, def.baseSalary * 5, `💼 To hire a ${role} you need $${fmt(def.baseSalary * 5)} in the bank (5 days of salary). Short by $${fmt(def.baseSalary * 5 - G.spendingPower())}.`);
    }
    const name = pick(S, FIRST_NAMES);
    S.staff = [...S.staff, { id: nextNumericId(S.staff), name, role, salary: def.baseSalary, skill: 1 + rand() * 2, happiness: 3 + rand() * 2 }];
    G.pay(def.baseSalary);
    G.notify(`Hired ${name} as a new ${role} for $${def.baseSalary}/day`);
    return { ok: true };
  },

  FIRE_STAFF(G, { staffId }) {
    const e = G.S.staff.find((s) => s.id === staffId);
    if (!e) return reject('unknown_staff');
    G.S.staff = G.S.staff.filter((s) => s.id !== staffId);
    G.notify(`Fired ${e.name} from their position as ${e.role}`);
    return { ok: true };
  },

  TRAIN_STAFF(G, { trainingId, staffId }) {
    const { S } = G;
    const training = TRAINING_PROGRAMS.find((t) => t.id === trainingId);
    const e = S.staff.find((s) => s.id === staffId);
    if (!training || !e) return reject('unknown_training_or_staff');
    if (G.spendingPower() < training.cost) {
      G.notify(`Could not start training. Need $${training.cost}, but only have $${fmt(G.spendingPower())}.`, false, 'error');
      return reject('insufficient_funds');
    }
    G.pay(training.cost);
    S.staff = S.staff.map((s) =>
      s.id === staffId ? { ...s, skill: Math.min(5, s.skill + training.skillBoost), happiness: Math.min(5, s.happiness + training.happiness) } : s
    );
    G.notify(`${e.name} completed "${training.name}" training. Skills improved!`, false, 'training');
    return { ok: true };
  },

  BUILD_FACILITY(G, { facilityType }) {
    const { S } = G;
    const ft = FACILITY_TYPES.find((f) => f.type === facilityType);
    if (!ft) return reject('unknown_facility');
    if (locked(G, 'facility', facilityType, `The ${facilityType}`)) return reject('locked');
    // Premium facilities also cost coins (credits), paid from credits only.
    const coins = ft.isPremium ? ft.coinCost || 0 : 0;
    if (coins && S.credits < coins) {
      return insufficient(G, coins, `✨ ${facilityType} is a PREMIUM facility: it needs ${fmt(coins)} coins (you have ${fmt(S.credits)}) plus $${fmt(ft.baseCost)}.`);
    }
    if (G.spendingPower() - coins < ft.baseCost) {
      return insufficient(
        G,
        ft.baseCost,
        ft.isPremium
          ? `✨ ${facilityType} is a PREMIUM facility! Costs ${fmt(ft.coinCost)} coins + $${fmt(ft.baseCost)}. 💎 Buy Credits now!`
          : `🏗️ ${facilityType} costs $${fmt(ft.baseCost)}. Short by $${fmt(ft.baseCost - G.spendingPower())}. 💎 Get Credits to build faster!`
      );
    }
    if (S.facilities.some((f) => f.name === facilityType)) {
      G.notify(`You already have a ${facilityType}!`, true, 'error');
      return reject('already_built');
    }
    for (const req of ft.requiredStaff || []) {
      if (S.staff.filter((s) => s.role === req.role).length < req.count) {
        G.notify(`You need to hire a ${req.role} before building a ${facilityType}!`, true, 'error');
        return reject('missing_staff');
      }
    }
    S.facilities = [...S.facilities, { id: nextNumericId(S.facilities), name: facilityType, level: 1, upkeep: ft.upkeep }];
    // FIX: the coin price of premium facilities was shown but never charged.
    S.credits -= coins;
    G.pay(ft.baseCost);
    G.notify(`Built a new ${facilityType} for $${fmt(ft.baseCost)}`, true, 'success');
    return { ok: true };
  },

  UPGRADE_FACILITY(G, { facilityId }) {
    const { S } = G;
    const f = S.facilities.find((x) => x.id === facilityId);
    if (!f) return reject('unknown_facility');
    const cost = 5000 * f.level;
    if (G.spendingPower() < cost) {
      G.notify(`Cannot afford to upgrade ${f.name}! Need $${cost}, but only have $${fmt(G.spendingPower())}.`);
      return reject('insufficient_funds');
    }
    if (f.level >= 5) {
      G.notify(`${f.name} is already at maximum level!`);
      return reject('max_level');
    }
    S.facilities = S.facilities.map((x) => (x.id === facilityId ? { ...x, level: x.level + 1, upkeep: Math.round(x.upkeep * 1.2) } : x));
    G.pay(cost);
    G.notify(`Upgraded ${f.name} to level ${f.level + 1}`);
    return { ok: true };
  },

  /** Price of one menu item (food & drink) or the entry fee (other facilities). */
  SET_FACILITY_PRICE(G, { facilityId, itemId, price }) {
    const { S } = G;
    const f = S.facilities.find((x) => x.id === facilityId);
    if (!f || f.name === 'Lobby') return reject('unknown_facility');
    const offer = facilityOffer(f);
    const item = offer.kind === 'menu' ? offer.items.find((i) => i.id === itemId) : offer.items[0];
    if (!item) return reject('unknown_item');
    const p = Math.round(Number(price));
    if (!Number.isFinite(p) || p < 1 || p > item.base * 5) return reject('invalid_price');
    S.facilities = S.facilities.map((x) => {
      if (x.id !== facilityId) return x;
      return offer.kind === 'menu' ? { ...x, prices: { ...(x.prices || {}), [item.id]: p } } : { ...x, fee: p };
    });
    return { ok: true };
  },

  /** Choose an insurance plan ('none' | 'basic' | 'full'); the premium is charged daily. */
  SET_INSURANCE(G, { plan }) {
    if (!Object.prototype.hasOwnProperty.call(INSURANCE_PLANS, plan)) return reject('invalid_plan');
    G.S.insurance = plan;
    G.notify(plan === 'none' ? '⚠️ Insurance cancelled — you now pay the full cost of any disaster.' : `🛡️ Now insured: ${INSURANCE_PLANS[plan].name}.`, true, 'system');
    return { ok: true };
  },

  LAUNCH_CAMPAIGN(G, { campaignId }) {
    const { S } = G;
    const c = S.marketingCampaigns.find((x) => x.id === campaignId);
    if (!c || !CAMPAIGNS[campaignId]) return reject('unknown_campaign');
    if (locked(G, 'campaign', campaignId, `"${c.name}"`)) return reject('locked');
    if (c.active) return reject('already_active');
    // Price scales with the hotel (base + per room).
    const cost = campaignCost(S, campaignId);
    const { duration } = CAMPAIGNS[campaignId];
    if (G.spendingPower() < cost) {
      return insufficient(G, cost, `📢 "${c.name}" costs $${fmt(cost)} for your hotel. Short by $${fmt(cost - G.spendingPower())}.`);
    }
    G.pay(cost);
    S.marketingCampaigns = S.marketingCampaigns.map((x) =>
      x.id === campaignId ? { ...x, active: true, endDay: S.day + duration, paid: cost, extraGuests: 0, extraRevenue: 0 } : x
    );
    G.notify(`📢 Started "${c.name}" for ${duration} days ($${fmt(cost)}).`, true, 'marketing');
    return { ok: true };
  },

  SET_POLICY(G, { key, value }) {
    if (!Object.prototype.hasOwnProperty.call(POLICY_MESSAGES, key) || typeof value !== 'boolean') return reject('invalid_policy');
    G.S.policies = { ...G.S.policies, [key]: value };
    G.notify(`Policy change: ${POLICY_MESSAGES[key][value ? 0 : 1]}`, false, 'policy');
    return { ok: true };
  },

  CLAIM_SOCIAL_REWARD(G, { rewardId }) {
    const { S } = G;
    const amount = SOCIAL_REWARDS[rewardId];
    if (!amount) return reject('unknown_reward');
    if (S.claimedRewards.includes(rewardId)) return reject('already_claimed');
    S.claimedRewards = [...S.claimedRewards, rewardId];
    S.money += amount;
    G.emit({ kind: 'reward', type: 'money', amount });
    return { ok: true, amount };
  },

  CLAIM_AD_REWARD(G, { rewardId }) {
    const { S, t } = G;
    const def = AD_REWARDS[rewardId];
    if (!def) return reject('unknown_reward');
    const last = S.clock.ads[rewardId] || 0;
    if (last && t - last < def.cooldownMs) return reject('cooldown', { retryInMs: def.cooldownMs - (t - last) });
    S.clock.ads = { ...S.clock.ads, [rewardId]: t };
    S.money += def.amount;
    G.emit({ kind: 'reward', type: 'money', amount: def.amount });
    return { ok: true, amount: def.amount };
  },

  // doubled: the player watched a rewarded ad (trusted, like CLAIM_AD_REWARD)
  CLAIM_AWAY_EARNINGS(G, { doubled }) {
    const { S } = G;
    if (!S.away) return reject('nothing_to_claim');
    const amount = S.away.amount * (doubled === true ? 2 : 1);
    S.away = null;
    S.money += amount;
    G.emit({ kind: 'reward', type: 'money', amount });
    return { ok: true, amount };
  },

  SPIN_WHEEL(G) {
    const { S, t } = G;
    const date = utcDate(t);
    if (S.clock.wheelDate !== date) S.clock = { ...S.clock, wheelDate: date, wheelSpins: 0 };
    if (S.clock.wheelSpins >= WHEEL_SPINS_PER_DAY) return reject('no_spins_left');
    S.clock = { ...S.clock, wheelSpins: S.clock.wheelSpins + 1 };
    const segment = pick(S, WHEEL_SEGMENTS);
    if (segment.type === 'money') S.money += segment.amount;
    else if (segment.type === 'credits') S.credits += segment.amount;
    else if (segment.type === 'reputation') S.reputation = clamp(S.reputation + segment.amount, 1, 5);
    G.emit({ kind: 'wheel', segment, spinsLeft: WHEEL_SPINS_PER_DAY - S.clock.wheelSpins });
    return { ok: true, segment };
  },

  VISIT_HOTEL(G, { name }) {
    const { S } = G;
    if (!S.competitors.some((c) => c.name === name)) return reject('unknown_hotel');
    // FIX: visits reset every game day (~3 s), so cash could be farmed. Now 3 per real (UTC) day.
    const date = utcDate(G.t);
    if (S.clock.visitDate !== date) S.clock = { ...S.clock, visitDate: date, visited: [] };
    if (S.clock.visited.includes(name)) return reject('already_visited');
    if (S.clock.visited.length >= HOTEL_VISITS_PER_DAY) return reject('no_visits_left');
    S.clock = { ...S.clock, visited: [...S.clock.visited, name] };
    const reward = Math.floor(500 + G.rand() * 1000);
    S.money += reward;
    G.notify(`🏨 Visited ${name}! Earned ${reward} coins for insights!`, false, 'reward');
    G.emit({ kind: 'reward', type: 'money', amount: reward });
    return { ok: true, amount: reward };
  },

  /**
   * Coins bought with real money or granted by the server (daily rewards…).
   * `ref` is the server credit-transaction id; the server verifies it before
   * replaying, and the engine guarantees each ref is applied at most once.
   */
  BUY_PLOT(G) {
    const { S } = G;
    const price = nextPlotPrice(S);
    if (G.spendingPower() < price) return insufficient(G, price, `🏞️ The next plot of land costs $${fmt(price)}. You need $${fmt(price - G.spendingPower())} more.`);
    const plots = plotsOwned(S) + 1;
    G.pay(price);
    S.land = { plots, paid: ((S.land && S.land.paid) || 0) + price };
    G.notify(`🏞️ Bought plot ${plots} for $${fmt(price)} — room for ${roomCapacity(S)} rooms.`, true, 'success');
    G.emit({ kind: 'landBought', plots, price });
    return { ok: true };
  },

  ACQUIRE_HOTEL(G, { competitorId }) {
    const { S } = G;
    const c = S.competitors.find((x) => x.id === competitorId);
    if (!c) return reject('unknown_competitor');
    const offer = acquisitionOffer(S, c);
    if (offer.locked) {
      G.notify(`🔒 Buying rival hotels unlocks at hotel level ${offer.unlockLevel}.`, false, 'info');
      return reject('locked');
    }
    if (offer.lastRivals) {
      G.notify('The town needs some competition: you can\'t buy the last rival hotels.', false, 'info');
      return reject('last_rivals');
    }
    if (G.spendingPower() < offer.price) return insufficient(G, offer.price, `🏨 ${c.name} would cost $${fmt(offer.price)}. You need $${fmt(offer.price - G.spendingPower())} more.`);
    // Its rooms join your hotel at a type matching its prices, with its land.
    const type = c.avgRoomPrice >= 400 ? 'Executive' : c.avgRoomPrice >= 200 ? 'Suite' : c.avgRoomPrice >= 100 ? 'Deluxe' : 'Standard';
    const rt = ROOM_TYPES.find((r) => r.type === type);
    let id = nextNumericId(S.rooms);
    const added = Array.from({ length: c.rooms }, () => ({ id: id++, type, price: rt.basePrice, occupied: false, quality: 2, guest: null }));
    G.pay(offer.price);
    S.land = { plots: plotsOwned(S) + Math.ceil(c.rooms / ROOMS_PER_PLOT), paid: ((S.land && S.land.paid) || 0) + Math.round(offer.price * 0.3) };
    S.rooms = [...S.rooms, ...added];
    S.competitors = S.competitors.filter((x) => x.id !== c.id);
    S.pendingRivals = [...(S.pendingRivals || []), { day: S.day + ACQUISITION.newRivalAfterDays }];
    G.notify(`🤝 You bought ${c.name} for $${fmt(offer.price)}: +${c.rooms} ${type} rooms. Hire staff for them — and watch for a new hotel opening in town.`, true, 'success');
    G.emit({ kind: 'acquired', name: c.name, rooms: c.rooms, price: offer.price });
    return { ok: true };
  },

  RECEIVE_COINS(G, { ref, amount }) {
    const { S } = G;
    const n = Number(amount);
    if (typeof ref !== 'string' || !ref || !Number.isInteger(n) || n <= 0) return reject('invalid_grant');
    if (S.appliedGrants.includes(ref)) return reject('already_applied');
    S.appliedGrants = [...S.appliedGrants, ref];
    S.credits += n;
    G.emit({ kind: 'reward', type: 'credits', amount: n });
    coverDebtWithCoins(G); // a purchase made to escape debt works straight away
    return { ok: true };
  },
};
